      // your API key
      mapKey: 'tLyW2vk0aY3yfQLu8ZPy986mAgaW8igMYufv3BLY',
      // your map key
      center: [105.85242472181584, 21.029579719995272],
      // Kinh độ, vĩ độ
      zoom: 14,
      // Độ zoom mặc định
      radiusInMeters: 100
    };
  },
  mounted() {
    this.initMap();
  },
  watch: {
    selectedLocation: 'moveToLocation'
  },
  methods: {
    initMap() {
      const map = new maplibregl.Map({
        container: 'map',
        style: `${this.mapUrl}goong_map_web.json?api_key=${this.mapKey}`,
        center: [this.selectedLocation[0], this.selectedLocation[1]],
        zoom: this.zoom
      });
      map.on('load', () => {
        // const circleData = {
