        //         'geometry': {
        //             'type': 'Polygon',
        //             'coordinates': [this.drawCircle(this.center, this.radiusInMeters)]
        //         }
        //     }]
        // };

        // map.addSource('circle', {
        //     'type': 'geojson',
        //     'data': circleData
        // });

        const lngLat = [...this.center];
        console.log("marker LngLat: ", lngLat);
        const marker = new maplibregl.Marker({
          color: "#FF0000",
          draggable: false
        }) // Đổi màu để dễ nhận diện
        .setLngLat(lngLat).addTo(map);
        console.log("Marker đã được thêm:", marker);
        // map.addLayer({
        //     id: 'circle',
        //     type: 'fill',
        //     source: 'circle',
        //     layout: {},
        //     paint: {
        //         'fill-color': '#588888',
        //         'fill-opacity': 0.5
        //     }
        // });
      });
      this.map = map; // Lưu map vào this.map để sử dụng ở các phương thức khác
    },
    moveToLocation(newLocation) {
      this.map.flyTo({
        center: newLocation,
        essential: true
      });
      this.addMarkerAndCircleAround(newLocation);
    },
    removeLayer(layerId) {
      if (this.map.getLayer(layerId)) {
        this.map.removeLayer(layerId);
      }
    },
    addMarker(lngLat) {
      new maplibregl.Marker().setLngLat(lngLat).addTo(this.map);
    },
    addMarkerAndCircleAround(lngLat) {
      console.log('Adding circle and marker at:', lngLat, 'with radius:', this.radiusInMeters);

      // Thêm marker tại vị trí mới
      const marker = new maplibregl.Marker().setLngLat(lngLat).addTo(this.map);
      if (marker) {
        console.log('Marker added successfully at:', lngLat);
      } else {
        console.error('Failed to add marker at:', lngLat);
      }

      // Xóa vòng tròn cũ nếu có
      this.removeLayer('circle');

      // Tạo dữ liệu cho vòng tròn
      const circleData = {
        'type': 'FeatureCollection',
        'features': [{
          'type': 'Feature',
          'geometry': {
            'type': 'Polygon',
            'coordinates': [this.drawCircle(lngLat, this.radiusInMeters)]
          }
        }]
      };

      // Kiểm tra xem nguồn đã tồn tại chưa trước khi thêm
      if (this.map.getSource('circle')) {
        this.map.removeSource('circle');
      }

      // Thêm source cho vòng tròn
      this.map.addSource('circle', {
        'type': 'geojson',
        'data': circleData
      });

      // Thêm layer cho vòng tròn
      this.map.addLayer({
        'id': 'circle',
        'type': 'fill',
        'source': 'circle',
        'layout': {},
        'paint': {
          'fill-color': '#588888',
          'fill-opacity': 0.5
        }
      });

      // Di chuyển đến vị trí mới
      this.map.flyTo({
        center: lngLat,
        zoom: 14
      });
    },
    drawCircle(center, radius) {
      const points = 64; // Số điểm để vẽ vòng tròn
      const coords = [];
      for (let i = 0; i <= points; i++) {
        const angle = i / points * 2 * Math.PI; // Tính toán góc
        const dx = radius * Math.cos(angle); // Tính toán độ dịch chuyển theo kinh độ
        const dy = radius * Math.sin(angle); // Tính toán độ dịch chuyển theo vĩ độ
        coords.push([center[0] + dx / 111320,
        // Kinh độ
        center[1] + dy / 110574 // Vĩ độ
        ]);
      }
      coords.push(coords[0]); // Đảm bảo vòng tròn khép kín

      return coords;
    }
  }
};
